import os
import base64
import requests

def score_image_safety(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Missing OPENAI_API_KEY")

    if isinstance(payload, bytes):
        image_bytes = payload
    elif isinstance(payload, str) and payload.startswith("data:"):
        image_bytes = base64.b64decode(payload.split(",", 1)[1])
    elif isinstance(payload, str):
        with open(payload, "rb") as f:
            image_bytes = f.read()
    elif isinstance(payload, dict) and "image_bytes" in payload:
        image_bytes = payload["image_bytes"]
        if isinstance(image_bytes, str):
            image_bytes = base64.b64decode(image_bytes)
    else:
        raise TypeError("payload must be bytes, a file path, a data URL, or a dict with image_bytes")

    image_b64 = base64.b64encode(image_bytes).decode("utf-8")
    model = config.get("model", "gpt-4o-mini")
    prompt = config.get(
        "prompt",
        "Inspect the image for unsafe or policy-sensitive visual content. "
        "Return JSON with keys: unsafe (boolean), categories (array of strings), "
        "confidence (number 0-1), and rationale (string)."
    )

    headers = {
        "Authorization": f"Bearer {api_key}",
        "Content-Type": "application/json",
    }
    body = {
        "model": model,
        "response_format": {"type": "json_object"},
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": prompt},
                    {
                        "type": "image_url",
                        "image_url": {"url": f"data:image/png;base64,{image_b64}"},
                    },
                ],
            }
        ],
        "max_tokens": config.get("max_tokens", 300),
    }

    resp = requests.post("https://api.openai.com/v1/chat/completions", headers=headers, json=body, timeout=config.get("timeout", 60))
    resp.raise_for_status()
    data = resp.json()
    content = data["choices"][0]["message"]["content"]

    try:
        result = __import__("json").loads(content)
    except Exception:
        result = {"unsafe": None, "categories": [], "confidence": None, "rationale": content}
    return result
